/* localized accessors — never mutate COACH; pick the language at read time */
function coachFor(id){
  const c = COACH[id];
  if(!c) return null;
  const L = (typeof S!=='undefined' && S.lang==='en') ? 'en' : 'mn';
  return {
    ...c,
    form: c.form[L], mistakes: c.mistakes[L], tips: c.tips[L],
    progNames: c.prog.map(p=>p[L]),
    next: c.prog[c.step+1] ? c.prog[c.step+1][L] : null,
    prev: c.step>0 ? c.prog[c.step-1][L] : null,
  };
}
